-- Unit identifiers describe banner formats, not verified visitor devices. No report data is changed.
create or replace function cbgpu_ad_reports.summary(data jsonb,kind text,zone text,from_date date,to_date date) returns jsonb language sql stable security definer set search_path='' as $$
with source as(select *,cbgpu_ad_reports.device(unit_id) device from jsonb_to_recordset(data) x(start_date date,end_date date,unit_id text,revenue_micros numeric,impressions numeric,clicks numeric,requests numeric)),
grouped as(select device,sum(revenue_micros) revenue,case when count(*)=count(impressions) then sum(impressions) end impressions,case when count(*)=count(clicks) then sum(clicks) end clicks,case when count(*)=count(requests) then sum(requests) end requests from source group by device),
daily as(select start_date as report_date,device,sum(revenue_micros) revenue from source where start_date=end_date group by 1,2),
monthly as(select to_char(start_date,'YYYY-MM') as month_label,device,sum(revenue_micros) revenue from source where date_trunc('month',start_date)=date_trunc('month',end_date) group by 1,2)
select jsonb_build_object('kind',kind,'currency','KRW','timezone',zone,'period_start',from_date,'period_end',to_date,'source','MANUAL_OFFICIAL_REPORT','official_console_verified',false,'device_basis','AD_UNIT_FORMAT','physical_device_revenue',null,'physical_device_reason','NO_OFFICIAL_DEVICE_DIMENSION',
'devices',coalesce((select jsonb_agg(jsonb_build_object('device',device,'device_basis','AD_UNIT_FORMAT','physical_device_revenue',null,'physical_device_reason','NO_OFFICIAL_DEVICE_DIMENSION','revenue_krw',cbgpu_ad_reports.decimal(revenue/1000000),'impressions',impressions::text,'clicks',clicks::text,'requests',requests::text,'ecpm_krw',case when impressions>0 then cbgpu_ad_reports.decimal(revenue*1000/impressions/1000000) end,'ctr_percent',case when impressions>0 and clicks is not null then cbgpu_ad_reports.decimal(clicks*100/impressions) end,'rpuv_krw',null,'rps_krw',null,'placement_revenue_krw',null,'fill_rate_percent',null,'fill_rate_reason','REQUEST_SEMANTICS_NOT_VERIFIED','denominator_reason','NO_ALIGNED_AGGREGATE','placement_reason','SHARED_AD_UNIT_ALL_PAGES') order by device) from grouped),'[]'::jsonb),
'daily',coalesce((select jsonb_agg(jsonb_build_object('date',report_date,'device',device,'device_basis','AD_UNIT_FORMAT','physical_device_revenue',null,'physical_device_reason','NO_OFFICIAL_DEVICE_DIMENSION','revenue_krw',cbgpu_ad_reports.decimal(revenue/1000000),'coverage_verified',false) order by report_date,device) from daily),'[]'::jsonb),
'monthly',coalesce((select jsonb_agg(jsonb_build_object('month',month_label,'device',device,'device_basis','AD_UNIT_FORMAT','physical_device_revenue',null,'physical_device_reason','NO_OFFICIAL_DEVICE_DIMENSION','revenue_krw',cbgpu_ad_reports.decimal(revenue/1000000),'coverage_verified',false) order by month_label,device) from monthly),'[]'::jsonb),
'warnings',to_jsonb(array_remove(array[case when jsonb_array_length(data)=0 then 'NO_REPORT_DATA' end,case when exists(select 1 from source where device='UNKNOWN') then 'UNKNOWN_AD_UNITS' end,case when exists(select 1 from source where date_trunc('month',start_date)<>date_trunc('month',end_date)) then 'CROSS_MONTH_PERIOD_NOT_ALLOCATED' end],null)))
$$;
revoke all on function cbgpu_ad_reports.summary(jsonb,text,text,date,date) from public,anon,authenticated,service_role;
